const cfg = $json;
const topics = String(cfg.trend_topics || '')
  .split('|')
  .map(t => t.trim())
  .filter(Boolean);

const days = Number(cfg.days_for_trends || 7);

return topics.map(topic => {
  const q = `${topic} when:${days}d`;
  return {
    json: {
      topic,
      rss_url: `https://news.google.com/rss/search?q=${encodeURIComponent(q)}&hl=en-US&gl=US&ceid=US:en`
    }
  };
});

const items = $input.all();
const seen = new Set();
const rows = [];

for (const item of items) {
  const j = item.json || {};
  const title = String(j.title || '').trim();
  const link = String(j.link || '').trim();
  const pubDate = String(j.pubDate || j.isoDate || '').trim();

  if (!title) continue;
  const key = title.toLowerCase();
  if (seen.has(key)) continue;
  seen.add(key);

  rows.push({ title, link, pubDate });
  if (rows.length >= 30) break;
}

const trend_results = rows
  .map((r, i) => `${i + 1}. ${r.title}\nDate: ${r.pubDate || 'N/A'}\nSource: ${r.link || 'N/A'}`)
  .join('\n\n');

return [{
  json: {
    trend_count: rows.length,
    trend_items: rows,
    trend_results
  }
}];

const raw = String($json.output ?? $json.text ?? '').trim();

function parseObject(text) {
  let t = text.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```$/i, '').trim();
  try { return JSON.parse(t); } catch (e) {}
  const start = t.indexOf('{');
  const end = t.lastIndexOf('}');
  if (start >= 0 && end > start) {
    try { return JSON.parse(t.slice(start, end + 1)); } catch (e) {}
  }
  return null;
}

const obj = parseObject(raw) || {};
const selected_topic = String(obj.selected_topic || raw || 'Artificial Intelligence trends').trim();
const reason = String(obj.reason || 'Selected from current trend results.').trim();
const angle = String(obj.angle || selected_topic).trim();
const keywords = Array.isArray(obj.keywords) ? obj.keywords : [];

return [{ json: { selected_topic, reason, angle, keywords, raw_selection: raw } }];

const topic = String($json.selected_topic || '').trim();
const days = Number($('CONFIG - Settings').first().json.days_for_research || 14);
const q = `${topic} statistics analysis business technology when:${days}d`;

return [{
  json: {
    ...$json,
    research_url: `https://news.google.com/rss/search?q=${encodeURIComponent(q)}&hl=en-US&gl=US&ceid=US:en`
  }
}];

const items = $input.all();
const selected = $('Parse Selected Topic').first().json;
const seen = new Set();
const sources = [];

for (const item of items) {
  const j = item.json || {};
  const title = String(j.title || '').trim();
  const link = String(j.link || '').trim();
  const pubDate = String(j.pubDate || j.isoDate || '').trim();
  if (!title) continue;

  const key = title.toLowerCase();
  if (seen.has(key)) continue;
  seen.add(key);

  sources.push({ title, link, pubDate });
  if (sources.length >= 5) break;
}

const source_text = sources
  .map((s, i) => `Source ${i + 1}: ${s.title}\nDate: ${s.pubDate || 'N/A'}\nURL: ${s.link || 'N/A'}`)
  .join('\n\n');

return [{
  json: {
    selected_topic: selected.selected_topic,
    reason: selected.reason,
    angle: selected.angle,
    sources,
    source_text,
    source_links: sources.map(s => s.link).filter(Boolean).join(' | ')
  }
}];

const raw = String($json.output ?? '').trim();

function parseObject(text) {
  let t = text.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```$/i, '').trim();
  try { return JSON.parse(t); } catch (e) {}
  const a = t.indexOf('{'), b = t.lastIndexOf('}');
  if (a >= 0 && b > a) {
    try { return JSON.parse(t.slice(a, b + 1)); } catch (e) {}
  }
