}

const obj = parseObject(raw);
const research = $('Extract Sources').first().json;
const post_text = String(obj.post_text || raw).trim();
const hashtags = String(obj.hashtags || '').trim();
const image_idea = String(obj.image_idea || '').trim();
const alt_text = String(obj.alt_text || '').trim();

return [{
  json: {
    topic: research.selected_topic,
    angle: research.angle,
    selected_reason: research.reason,
    post_text,
    hashtags,
    linkedin_post: hashtags ? `${post_text}\n\n${hashtags}` : post_text,
    image_idea,
    alt_text,
    source_text: research.source_text,
    source_links: research.source_links,
    word_count: post_text.split(/\s+/).filter(Boolean).length
  }
}];

